    row_segments = [(r, min(cs), max(cs)) for r, cs in row_groups.items() if len(cs) >= 2]
    col_segments = [(c, min(rs), max(rs)) for c, rs in col_groups.items() if len(rs) >= 2]
    marked_rows = {r for r, a, b in row_segments}
    marked_cols = {c for c, a, b in col_segments}
    line_cells = set()
    for r, a, b in row_segments:
        line_cells.update((r, c) for c in range(w))
    for c, a, b in col_segments:
        line_cells.update((r, c) for r in range(h))
    seen = set()
    for r in range(h):
        for c in range(w):
            if out[r][c] != 2 or (r, c) in seen:
                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                x, y = stack.pop()
